$ErrorActionPreference = 'Stop'
$temp = [System.IO.Path]::GetFullPath($env:TEMP).TrimEnd('\') + '\'

function Assert-Safe($p) {
  if ([string]::IsNullOrWhiteSpace($p)) { throw "EMPTY PATH" }
  $full = [System.IO.Path]::GetFullPath($p)
  if (-not $full.StartsWith($temp, [System.StringComparison]::OrdinalIgnoreCase)) {
    throw "OUTSIDE TEMP: $full"
  }
  return $full
}
function Sum($p) {
  $s = Get-ChildItem -LiteralPath $p -Recurse -File -Force -ErrorAction SilentlyContinue |
       Measure-Object -Property Length -Sum
  return [double]$s.Sum
}

"=== RUNNING BROWSER PROCESSES (informational) ==="
Get-Process chrome,msedge,chromium,playwright -ErrorAction SilentlyContinue |
  Group-Object ProcessName | ForEach-Object { "$($_.Name): $($_.Count)" } | Out-String

$dirs = Get-ChildItem -LiteralPath $temp -Directory -Force -ErrorAction SilentlyContinue |
        Where-Object { $_.Name -like 'agent-browser-chrome-*' }
"Targets: $($dirs.Count) dirs"
$before = ($dirs | ForEach-Object { Sum $_.FullName } | Measure-Object -Sum).Sum
"Before GB: {0:N2}" -f ($before/1GB)

"=== DRY-RUN: first 5 + last 5 ==="
$dirs | Select-Object -First 5 | ForEach-Object { "  " + $_.FullName }
"  ..."
$dirs | Select-Object -Last 5 | ForEach-Object { "  " + $_.FullName }

$deleted = 0; $failed = 0; $freed = 0.0
foreach ($d in $dirs) {
  try {
    $full = Assert-Safe $d.FullName
    $sz = Sum $full
    Remove-Item -LiteralPath $full -Recurse -Force -ErrorAction Stop
    $deleted++; $freed += $sz
  } catch { $failed++ }
}
"Deleted: $deleted, Failed(locked/in-use): $failed"
"Freed GB: {0:N2}" -f ($freed/1GB)
$remain = Get-ChildItem -LiteralPath $temp -Directory -Force -ErrorAction SilentlyContinue |
          Where-Object { $_.Name -like 'agent-browser-chrome-*' }
"Remaining dirs: $($remain.Count)"
"Remaining GB: {0:N2}" -f ((($remain | ForEach-Object { Sum $_.FullName } | Measure-Object -Sum).Sum)/1GB)

$ErrorActionPreference = 'Stop'
$temp = [System.IO.Path]::GetFullPath($env:TEMP).TrimEnd('\') + '\'
function Assert-Safe($p) {
  if ([string]::IsNullOrWhiteSpace($p)) { throw "EMPTY PATH" }
  $full = [System.IO.Path]::GetFullPath($p)
  if (-not $full.StartsWith($temp, [System.StringComparison]::OrdinalIgnoreCase)) { throw "OUTSIDE TEMP: $full" }
  return $full
}
function Sum($p) {
  $s = Get-ChildItem -LiteralPath $p -Recurse -File -Force -ErrorAction SilentlyContinue |
       Measure-Object -Property Length -Sum
  return [double]$s.Sum
}
$all = Get-ChildItem -LiteralPath $temp -Directory -Force -ErrorAction SilentlyContinue |
       Where-Object { $_.Name -like 'dsh-workspace-changes-*' } |
       Sort-Object LastWriteTime -Descending
"Total dirs: $($all.Count)"
"=== 2 NEWEST (KEEP) ==="
$all | Select-Object -First 2 | ForEach-Object { "{0:yyyy-MM-dd HH:mm}  {1}" -f $_.LastWriteTime, $_.Name }
$toDel = $all | Select-Object -Skip 2
"To delete: $($toDel.Count)"
$before = ($toDel | ForEach-Object { Sum $_.FullName } | Measure-Object -Sum).Sum
"To free GB: {0:N2}" -f ($before/1GB)
$deleted=0; $failed=0; $freed=0.0
foreach ($d in $toDel) {
  try {
    $full = Assert-Safe $d.FullName
    $sz = Sum $full
    Remove-Item -LiteralPath $full -Recurse -Force -ErrorAction Stop
    $deleted++; $freed += $sz
  } catch { $failed++ }
}
"Deleted: $deleted, Failed: $failed"
"Freed GB: {0:N2}" -f ($freed/1GB)
$remain = Get-ChildItem -LiteralPath $temp -Directory -Force -ErrorAction SilentlyContinue |
          Where-Object { $_.Name -like 'dsh-workspace-changes-*' }
"Remaining dirs: $($remain.Count)"

$ErrorActionPreference = 'SilentlyContinue'
function Sum($p) {
  if (-not (Test-Path -LiteralPath $p)) { return 0 }
  $s = Get-ChildItem -LiteralPath $p -Recurse -File -Force -ErrorAction SilentlyContinue |
       Measure-Object -Property Length -Sum
  return [double]$s.Sum
}
function Breakdown($root, $title, $n) {
  "=== $title ==="
  $rows = foreach ($i in Get-ChildItem -LiteralPath $root -Directory -Force -ErrorAction SilentlyContinue) {
    [pscustomobject]@{ Name=$i.Name; GB=[math]::Round((Sum $i.FullName)/1GB,2) }
  }
  $rows | Sort-Object GB -Descending | Select-Object -First $n | Format-Table -AutoSize | Out-String -Width 160
}
"=== ALL TOP-LEVEL (post-cleanup) ==="
Get-ChildItem C:\ -Directory -Force -ErrorAction SilentlyContinue | ForEach-Object {
  [pscustomobject]@{ Name=$_.Name; GB=[math]::Round((Sum $_.FullName)/1GB,2) }
} | Sort-Object GB -Descending | Format-Table -AutoSize | Out-String -Width 160

"=== ROOT SYSTEM FILES ==="
foreach ($f in @('C:\hiberfil.sys','C:\pagefile.sys','C:\swapfile.sys')) {
  $i = Get-Item -LiteralPath $f -Force -ErrorAction SilentlyContinue
  if ($i) { "{0}  {1:N2} GB" -f $f, ($i.Length/1GB) } else { "$f  absent/no-access" }
}
